149	
150	    /**
151	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
152	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
153	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
154	     *
155	     * @param lastName the owner's last name
156	     * @return the assigned customer code
157	     */
158	    private String nextCustomerCode(String lastName) {
159	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
160	        int sequence = this.clinicService.findAllOwners().size() + 1;
161	        return String.format("%s-%04d", last3, sequence);
162	    }
163	
164	    /**
165	     * Counts the existing owners that already share the given firstName and lastName, compared
166	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
167	     * the owners that pre-existed this create.
168	     *
169	     * @param firstName the new owner's first name
170	     * @param lastName  the new owner's last name
171	     * @return the number of existing namesakes
172	     */
173	    private int countNamesakes(String firstName, String lastName) {
174	        return (int) this.clinicService.findAllOwners().stream()
175	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
176	                && equalsIgnoreCase(existing.getLastName(), lastName))
177	            .count();
178	    }
179	
180	    private boolean equalsIgnoreCase(String a, String b) {
181	        return a == null ? b == null : a.equalsIgnoreCase(b);
182	    }
183	
184	    /**
185	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
186	     * offending field so the client learns about all of them at once.
187	     *
188	     * @param ownerFieldsDto the submitted owner fields
189	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
190	     *                                     missing or blank
191	     */
192	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
193	        List<String> errors = new ArrayList<>();
194	        if (isBlank(ownerFieldsDto.getFirstName())) {
195	            errors.add("firstName");
196	        }
197	        if (isBlank(ownerFieldsDto.getLastName())) {
198	            errors.add("lastName");
199	        }
200	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
201	            errors.add("address");
202	        }
203	        if (isBlank(ownerFieldsDto.getCity())) {
204	            errors.add("city");
205	        }
206	        if (isBlank(ownerFieldsDto.getTelephone())) {
207	            errors.add("telephone");
208	        }
209	        if (!errors.isEmpty()) {
210	            throw new MissingOwnerFieldsException(errors);
211	        }
212	    }
213	
214	    private boolean isBlank(String value) {
215	        return value == null || value.isBlank();
216	    }
217	
218	    /**
219	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
220	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
221	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
222	     * followed by 8 to 15 digits.
223	     *
224	     * @param telephone the raw telephone value as submitted
225	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
226	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
227	     */
228	    private String normalizeTelephone(String telephone) {
229	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
230	        String nationalSignificantNumber;
231	        if (cleaned.startsWith("+")) {
232	            nationalSignificantNumber = cleaned.substring(1);
233	        } else {
234	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
235	            nationalSignificantNumber = "61" + national;
236	        }
237	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
238	            throw new InvalidTelephoneException(telephone);
239	        }
240	        return "+" + nationalSignificantNumber;
241	    }
242	
243	    /**
244	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
245	     * value is treated as absent and returns {@code null}); when present the value must be a
246	     * syntactically valid address, and is stored and returned lower-cased.
247	     *
248	     * @param email the raw email value as submitted, may be {@code null}
249	     * @return the lower-cased email, or {@code null} when none was supplied
250	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
251	     */
252	    private String normalizeEmail(String email) {
253	        if (email == null || email.isBlank()) {
254	            return null;
255	        }
256	        String normalized = email.trim().toLowerCase();
257	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
258	            throw new InvalidEmailException(email);
259	        }
260	        return normalized;
261	    }
262	
263	    /**
264	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
265	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
266	     * comparison, so numbers that differ only in formatting still count as duplicates.
267	     *
268	     * @param e164Telephone the E.164 telephone of the owner being created
269	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
270	     */
271	    private void rejectDuplicateTelephone(String e164Telephone) {
272	        boolean inUse = this.clinicService.findAllOwners().stream()
273	            .map(Owner::getTelephone)
274	            .filter(existing -> existing != null)
275	            .map(this::toComparableTelephone)
276	            .filter(existing -> existing != null)
277	            .anyMatch(e164Telephone::equals);
278	        if (inUse) {
279	            throw new DuplicateTelephoneException(e164Telephone);
280	        }
281	    }
282	
283	    /**
284	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
285	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
286	     * than aborting the whole create.
287	     */
288	    private String toComparableTelephone(String telephone) {
289	        try {
290	            return normalizeTelephone(telephone);
291	        } catch (InvalidTelephoneException ex) {
292	            return null;
293	        }
294	    }
295	
296	    /**
297	     * Applies the household rule to an owner being created. An owner belongs to the same household
298	     * as an existing owner when their lastName and address both match (compared case-insensitively
299	     * with runs of whitespace collapsed to a single space).
300	     *
301	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
302	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
303	     * does, the new owner and every existing owner in the household are assigned the same stable
304	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
305	     *
306	     * @param owner            the owner being created
307	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
308	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
309	     *                                     the request did not opt in with {@code sharesHousehold=true}
310	     */
311	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
312	        String lastNameKey = toHouseholdKey(owner.getLastName());
313	        String addressKey = toHouseholdKey(owner.getAddress());
314	        List<Owner> household = this.clinicService.findAllOwners().stream()
315	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
316	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
317	            .toList();
318	        if (household.isEmpty()) {
319	            return;
320	        }
321	        if (!Boolean.TRUE.equals(sharesHousehold)) {
322	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
323	        }
324	        String householdId = householdId(lastNameKey, addressKey);
325	        owner.setHouseholdId(householdId);
326	        for (Owner existing : household) {
327	            if (!householdId.equals(existing.getHouseholdId())) {
328	                existing.setHouseholdId(householdId);
329	                this.clinicService.saveOwner(existing);
330	            }
331	        }
332	    }
333	
334	    /**
335	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
336	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
337	     * lastName and address keys. Being a pure function of the household, every owner in it derives
338	     * the same value regardless of creation order.
339	     *
340	     * @param lastNameKey the normalized household lastName key
341	     * @param addressKey  the normalized household address key
342	     * @return the household identifier
343	     */
344	    private String householdId(String lastNameKey, String addressKey) {
345	        try {
346	            byte[] digest = MessageDigest.getInstance("SHA-256")
347	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
348	            StringBuilder hex = new StringBuilder(digest.length * 2);
349	            for (byte b : digest) {
350	                hex.append(String.format("%02x", b));
351	            }
352	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
353	        } catch (NoSuchAlgorithmException ex) {
354	            throw new IllegalStateException("SHA-256 not available", ex);
355	        }
356	    }
357	
358	    /**
359	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
360	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
361	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
362	     * string.
363	     */
364	    private String toHouseholdKey(String value) {
365	        if (value == null) {
366	            return "";
367	        }
368	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
369	    }
370	
371	    /**
372	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
373	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
374	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
375	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
376	     * value, or one that is blank once trimmed, normalizes to an empty string.
377	     *
378	     * @param address the raw address value as submitted, may be {@code null}
379	     * @return the normalized address, or an empty string when none was supplied
380	     */
381	    private String normalizeAddress(String address) {
382	        if (address == null) {
383	            return "";
384	        }
385	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
386	        if (collapsed.isEmpty()) {
387	            return "";
388	        }
389	        String[] tokens = collapsed.split(" ");
390	        StringBuilder normalized = new StringBuilder(collapsed.length());
391	        for (int i = 0; i < tokens.length; i++) {
392	            if (i > 0) {
393	                normalized.append(' ');
394	            }
395	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
396	        }
397	        return normalized.toString();
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
403	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
404	        if (currentOwner == null) {
405	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
406	        }
407	        currentOwner.setAddress(ownerFieldsDto.getAddress());
408	        currentOwner.setCity(ownerFieldsDto.getCity());
409	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
410	        currentOwner.setLastName(ownerFieldsDto.getLastName());
411	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
412	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
413	        this.clinicService.saveOwner(currentOwner);
414	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
415	    }
416	
417	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
418	    @Transactional
419	    @Override
420	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
421	        Owner owner = this.clinicService.findOwnerById(ownerId);
422	        if (owner == null) {
423	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
424	        }
425	        this.clinicService.deleteOwner(owner);
426	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
427	    }
428	
429	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
430	    @Override
431	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
432	        Owner owner = this.clinicService.findOwnerById(ownerId);
433	        if (owner == null) {
434	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
435	        }
436	        HttpHeaders headers = new HttpHeaders();
437	        Pet pet = petMapper.toPet(petFieldsDto);
438	        owner.setId(ownerId);
439	        pet.setOwner(owner);
440	        pet.getType().setName(null);
441	        this.clinicService.savePet(pet);
442	        PetDto petDto = petMapper.toPetDto(pet);
443	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
444	            .buildAndExpand(pet.getId()).toUri());
445	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
451	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
452	        if (currentOwner != null) {
453	            Pet currentPet = this.clinicService.findPetById(petId);
454	            if (currentPet != null) {
455	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
456	                currentPet.setName(petFieldsDto.getName());
457	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
458	                this.clinicService.savePet(currentPet);
459	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
460	            }
461	        }
462	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	    }
464	
465	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
466	    @Override
467	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
468	        HttpHeaders headers = new HttpHeaders();
469	        Visit visit = visitMapper.toVisit(visitFieldsDto);
470	        Pet pet = new Pet();
471	        pet.setId(petId);
472	        visit.setPet(pet);
473	        this.clinicService.saveVisit(visit);
474	        VisitDto visitDto = visitMapper.toVisitDto(visit);
475	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
476	            .buildAndExpand(visit.getId()).toUri());
477	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
478	    }
479	
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
484	        Owner owner = this.clinicService.findOwnerById(ownerId);
485	        if (owner != null) {
486	            Pet pet = owner.getPet(petId);
487	            if (pet != null) {
488	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
489	            }
490	        }
491	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
492	    }
493	}
